'use strict';
const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let tasks=[],courses=[],connection={},current=null,step=1,method='manual',selectedPage=0,selectedVersion=null,poll=null,actionPending=false,query='',changeDrafts={},viewEpoch=0,afterSave=null,unmountReferenceUpload=null,outlineDraft=null,outlineViewing=false,progressClock=null,selectedHtmlVersion=null,showHtmlPreview=false;
const deletedTaskIds=new Set();
let deleteReturnId=null;
let outlineLayoutPicker=null;
const statuses={'html-ready':'可预览',prepared:'\u5f85\u53d1\u9001',draft:'草稿',manual:'外部制作中',running:'制作中',outline:'待确认大纲',complete:'待检查',ready:'可上课',failed:'制作失败',cancelled:'已取消'};
function notice(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function error(message){const e=$('pageError');e.textContent=teacherMessage(message);e.hidden=!message;if(message)e.scrollIntoView({block:'nearest'});}
async function api(url,body,verb){const response=await fetch(url,{method:verb||(body===undefined?'GET':'POST'),headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw new Error(result.error||'操作未完成，请重试。');return result;}
const endpoint=action=>`/api/ppt/tasks/${current.id}${action?'/'+action:''}`;
const download=(file,id=current.id)=>`/api/ppt/tasks/${id}/file?path=${encodeURIComponent(file)}`;
function tag(t){return `<span class="tag ${t.status==='ready'?'green':t.status==='failed'?'red':'blue'}">${statuses[t.status]||t.status}</span>`;}
function showModal(title,body,buttons){$('modalContent').innerHTML=`<h2 id="modalTitle">${esc(title)}</h2>${body}<p id="modalError" class="error-text" role="alert"></p><div class="modal-actions">${buttons}</div>`;$('modal').showModal();}
function stopPoll(){clearInterval(poll);poll=null;clearInterval(progressClock);progressClock=null;}
async function list(){viewEpoch++;stopPoll();current=null;location.hash='list';tasks=(await api('/api/ppt/tasks')).items;renderList();}
window.updatePptTasks=items=>{if(current)return;items=items.filter(t=>!deletedTaskIds.has(t.id));const changed=JSON.stringify(tasks)!==JSON.stringify(items);tasks=items;if(changed&&document.activeElement?.id!=='search')renderList();};
function courseCover(t){if(t.cover?.type==='html')return `<iframe tabindex="-1" title="${esc(t.title)}真实课件首页" sandbox="" loading="lazy" data-html-url="/api/ppt/tasks/${t.id}/html?version=${t.cover.version}&page=0"></iframe><span class="course-cover-status" role="status">正在加载真实首页…</span>`;if(t.cover?.type==='pptx')return `<img loading="lazy" alt="${esc(t.title)}真实PPT首页" src="/api/ppt/tasks/${t.id}/cover?v=${t.cover.version}">`;return `<div class="course-cover-empty"><b>▧</b><span>${t.status==='running'?'正在制作课件':'暂无课件预览'}</span></div>`;}
function renderList(){outlineDraft=null;unmountUpload();const found=tasks.filter(t=>!query||t.title.toLowerCase().includes(query.toLowerCase()));$('view').innerHTML=`<div class="content-width"><header class="management-list-head"><p>从教学想法到课堂演示，让每一页都有重点。</p><button class="primary" data-action="new">＋ 新建课件</button></header><div class="toolbar"><input id="search" placeholder="搜索课件名称" aria-label="搜索课件" value="${esc(query)}"><span class="count">共 ${found.length} 份课件</span></div><section class="course-card-grid" aria-label="课件列表">${found.length?found.map(t=>`<article class="course-card"><button class="course-cover" data-action="open" data-id="${t.id}" aria-label="查看${esc(t.title||'未命名课件')}">${courseCover(t)}</button><div class="course-card-info"><div class="course-card-heading"><h2 title="${esc(t.title)}">${esc(t.title||'未命名课件')}</h2>${tag(t)}</div><p>${esc(courses.find(c=>c.id===t.courseId)?.name||'未关联课程')} · ${t.minutes} 分钟${t.version?' · 版本 '+t.version:''}</p><footer><time>${esc(new Date(t.updatedAt).toLocaleString())}</time><div class="course-card-actions"><button class="text-button" data-action="open" data-id="${t.id}">${t.status==='draft'?'继续编辑':'查看课件'} →</button><button class="danger small" data-action="delete-task" data-id="${t.id}" aria-label="删除课件${esc(t.title||'未命名课件')}" ${t.status==='running'?'disabled title="请先取消制作后再删除"':''}>删除</button></div></footer></div></article>`).join(''):'<div class="empty-state"><h3>还没有课件</h3><p>新建一份课件，保存要求后即可选择制作方式。</p></div>'}</section></div>`;$('search').onchange=e=>{query=e.target.value;renderList();};fitCourseCovers();document.querySelectorAll('.course-cover iframe').forEach(frame=>window.PptHtmlPreview?.mount(frame,frame.parentElement.querySelector('.course-cover-status')));document.querySelectorAll('.course-cover img').forEach(img=>img.onerror=()=>{img.outerHTML='<div class="course-cover-empty"><b>▧</b><span>封面预览暂不可用，请打开课件查看</span></div>';});}
function fitCourseCovers(){document.querySelectorAll('.course-cover iframe').forEach(frame=>frame.style.transform='scale('+frame.parentElement.clientWidth/1280+')');}
window.addEventListener('resize',fitCourseCovers);
function workflowSteps(){const labels=['填写要求','选择方式','生成大纲','生成PPT'];let active=step;if(step>=3)active=outlineViewing||outlineEditing()||current.status==='outline'||current.run?.phase==='outline'&&current.status!=='html-ready'&&!['complete','ready'].includes(current.status)||['prepared','manual'].includes(current.status)?3:4;return {labels,active};}
function teacherMessage(value){return String(value??'').replace(/HTML课件/g,'课件').replace(/HTML/g,'课件').replace(/PPTX/g,'可编辑PPT');}
function frame(){const flow=workflowSteps();return `<div class="content-width"><nav class="breadcrumb" aria-label="面包屑"><button data-action="list">PPT管理</button><span>/</span><span>${esc(current.title||'新建课件')}</span></nav><header class="page-head"><div><h1>${step===1?'填写课件要求':esc(current.title)}</h1><p class="subline">要求只填一次，手动与平台调用共用。</p></div><div class="head-actions">${current.id?tag(current):''}<button data-action="list">返回列表</button></div></header><div class="flow-navigation"><nav class="flow-steps" style="--ppt-step-count:${flow.labels.length}" aria-label="制作流程">${flow.labels.map((s,i)=>`<div class="flow-step ${flow.active===i+1?'active':flow.active>i+1?'complete':''}" ${flow.active===i+1?'aria-current="step"':''}><i class="flow-number">${i+1}</i>${s}</div>`).join('')}</nav></div>`;}
function footer(){return `<div class="flow-footer"><button class="flow-back" data-action="back" ${current.status==='running'?'disabled':''}>← 上一步</button></div></div>`;}
function files(){return current.files?.map(f=>`<div class="file-chip"><a href="${download(f.file)}">${esc(f.name)}</a><button type="button" class="text-button" data-action="remove-file" data-id="${f.id}" aria-label="移除${esc(f.name)}">×</button></div>`).join('')||'';}
function creationModeField(){const sources=current.files.filter(f=>/\.pptx$/i.test(f.name)),updating=current.creationMode==='update';return `<section class="template-field"><h3>本次希望怎么制作？</h3><div class="creation-mode" role="group" aria-label="课件制作模式"><button type="button" data-action="creation-create" aria-pressed="${!updating}"><strong>新建内容</strong><span>根据教学要求组织新课件</span></button><button type="button" data-action="creation-update" aria-pressed="${updating}" ${sources.length?'':'disabled'}><strong>更新课件</strong><span>${sources.length?'保留原PPT内容，更新模板与排版':'上传PPTX参考资料后可选择'}</span></button></div>${updating?`<label for="sourceFileId">要更新的原稿</label><select id="sourceFileId">${sources.map(f=>`<option value="${f.id}" ${current.sourceFileId===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select><p class="helper">原稿决定内容，模板决定视觉。默认保留原页数、顺序、例题、数据及必要原图；内容变更先在大纲中确认。${current.sourcePageCount?`原稿 ${current.sourcePageCount} 页；${current.pageCount?'本次目标 '+current.pageCount+' 页，先确认拆合页方案。':'本次保留原稿页数。'}`:''}</p>`:''}</section>`;}
function requirements(){return `<div class="form-layout"><section class="panel"><div class="panel-heading"><h2>这节课的要求</h2></div><form id="requirements" novalidate><div class="fields"><div class="field wide"><label for="title">本课主题</label><input id="title" maxlength="80" value="${esc(current.title)}" required></div><div class="field"><label for="presenter">授课人 <em>选填，显示在封面</em></label><input id="presenter" maxlength="60" value="${esc(current.presenter||'')}" placeholder="例如：李老师"></div><div class="field"><label for="lessonDate">授课日期 <em>选填，显示在封面</em></label><input id="lessonDate" type="date" value="${esc(current.lessonDate||'')}"></div><div class="field"><label for="audience">授课对象</label><input id="audience" maxlength="100" value="${esc(current.audience)}" required placeholder="例如：高一，已学习古典概型"></div><div class="field"><label for="minutes">课时 <em>分钟</em></label><input id="minutes" type="number" min="5" max="240" value="${current.minutes||45}" required></div><div class="field"><label for="pageCount">PPT 页数 <em>页，可选</em></label><input id="pageCount" type="number" min="1" max="150" step="1" placeholder="${current.creationMode==='update'?'留空保留原页数':'留空自动安排'}" value="${current.pageCount??''}" aria-describedby="pageCountHint pageCountError"><p id="pageCountHint" class="helper">${current.creationMode==='update'?'默认保留原页数；指定不同页数时，先在大纲确认拆合页方案，不删内容凑页数。':'包含封面和结束页，共 1–150 页；页数越多，制作时间越长。'}</p><p id="pageCountError" class="error-text" role="alert"></p></div><div class="field"><label for="course">关联课程</label><select id="course"><option value="">暂不关联</option>${courses.map(c=>`<option value="${c.id}" ${current.courseId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="style">视觉风格</label><input id="style" maxlength="100" value="${esc(current.style||'清晰简洁，适合投影')}"></div><div class="field wide"><label for="content">教学内容或参考资料</label><textarea id="content" maxlength="12000" placeholder="知识点、教材章节或课堂安排">${esc(current.content)}</textarea><p class="helper">填写内容或上传参考资料，选一种即可。</p></div><div class="field wide"><div id="referenceUpload" class="reference-upload"></div><p id="referenceUploadError" class="error-text" role="alert" hidden></p><p class="helper">资料保存在本机；交给 WorkBuddy/CodeBuddy 制作时由其模型服务处理，请勿上传不宜外发的资料。</p></div></div>${creationModeField()}${templateField()}<details class="optional"><summary>补充要求（可选）</summary><div class="fields"><div class="field wide"><textarea id="extra" aria-label="补充要求" placeholder="可自由填写其他要求" maxlength="1000">${esc(current.extra)}</textarea></div></div></details><p id="formError" class="error-text" role="alert"></p><div class="savebar"><button type="button" data-action="list">返回列表</button><div><button type="button" data-action="save">保存草稿</button><button class="primary" type="submit">下一步：选择制作方式 →</button></div></div></form></section><aside class="aside-note"><h3>只填必要的，剩下交给 WorkBuddy</h3><ul><li>主题、对象和课时决定教学节奏。</li><li>先确认大纲，再制作完整课件。</li><li>任务与历史文件会保存在本机。</li></ul></aside></div>`;}
function methodPage(){return window.PptMethodView.methods({method,connection});}
function importBox(){return `<section class="aside-note"><h3>导回外部制作的课件</h3><p>选择真实PPTX，平台会检查文件并作为新版本保存。</p><input id="importFile" type="file" accept=".pptx" aria-label="导回PPTX"><button class="side-action" data-action="import">导入课件</button></section>`;}
function manualPage(){return `<div class="workspace"><section class="panel"><div class="panel-heading"><h2>复制后，交给 WorkBuddy</h2><span class="tag">手动调用</span></div><div class="manual-checklist"><div><b>01</b><strong>复制完整任务</strong><p>教学要求已经合并。</p></div><div><b>02</b><strong>在 WorkBuddy 粘贴</strong><p>再附上参考资料。</p></div><div><b>03</b><strong>确认大纲与成品</strong><p>在独立对话中继续修改。</p></div></div><div class="manual-actions"><button class="primary" data-action="copy">复制完整任务</button><button data-action="download-prompt">下载任务文本</button></div><div class="callout">附件不会随文字复制，请下载下列资料，另外附给 WorkBuddy。</div><div class="file-list">${current.template?`<a href="${download(current.template.file)}">${esc(current.template.name)}</a>`:''}${files().replaceAll('data-action="remove-file"','disabled data-action="none"')}</div><div class="savebar"><p class="muted">${current.status==='manual'?'已记录为外部制作中。':'发送后可标记进度，方便回来继续。'}</p><button data-action="sent">我已交给 WorkBuddy</button></div></section>${importBox()}</div>`;}
function outlineEditing(){return Boolean(outlineDraft&&current?.id&&outlineDraft.taskId===current.id);}
function outlineDirty(){return outlineEditing()&&JSON.stringify(outlineDraft.value)!==JSON.stringify(current.outline);}
function outlineTotal(){return outlineDraft.value.sections.reduce((sum,s)=>sum+(Number(s.minutes)||0),0);}
function updateOutlineTotal(){const target=$('outlineTotal');if(!target||!outlineEditing())return;const total=outlineTotal(),difference=current.minutes-total;target.textContent=`${outlineDraft.value.sections.length} 页${current.pageCount?` / 要求 ${current.pageCount} 页`:''} · 合计 ${total} / ${current.minutes} 分钟${Math.abs(difference)<.01?' · 时间已分配完成':difference>0?` · 还需分配 ${difference} 分钟`:` · 超出 ${-difference} 分钟`}`;target.classList.toggle('time-mismatch',Math.abs(difference)>.01);}
function fitOutlineTextareas(){document.querySelectorAll('#outlineEditor textarea').forEach(el=>{el.style.height='auto';el.style.height=Math.max(96,el.scrollHeight+2)+'px';});}
function outlineRoleLayout(i,total){const t=current.template,role=t?.roleFile&&(i===0?t.pageRoles?.cover:i===total-1?t.pageRoles?.ending:null);return role&&(t.pageRoles.layoutGroups||[]).find(g=>g.id===role.layoutId);}
function outlineLayouts(i,total){const special=outlineRoleLayout(i,total);return special?[special]:(current.template?.profile?.layoutGroups||[]);}
function outlineLayout(s,i,total){const groups=outlineLayouts(i,total);return outlineRoleLayout(i,total)||(s.layoutId?groups.find(g=>g.id===s.layoutId):groups[Math.min(i,groups.length-1)]);}
function outlineLayoutCard(s,i,total){const groups=outlineLayouts(i,total);if(!groups.length)return '';const group=outlineLayout(s,i,total),fixed=outlineRoleLayout(i,total);return `<aside class="outline-page-layout" id="outlineLayout${i}">${group?layoutDiagram(group):'<div class="outline-layout-missing">请重新选择页面布局</div>'}<div class="outline-layout-caption"><strong>${esc(group?.name||'布局不可用')}</strong>${fixed?'<small>专用布局</small>':''}</div><button type="button" class="text-button" data-action="choose-outline-layout" data-index="${i}">${fixed?'查看布局':'更换布局'}</button></aside>`;}
function outlineLayoutSelect(s,i){return outlineLayoutCard(s,i,outlineDraft.value.sections.length);}
function normalizeOutlineRoles(){const sections=outlineDraft.value.sections,roleIds=new Set((current.template?.pageRoles?.layoutGroups||[]).map(g=>g.id));sections.forEach((s,i)=>{const groups=outlineLayouts(i,sections.length);if(groups.length===1&&roleIds.has(groups[0].id))s.layoutId=groups[0].id;else if(roleIds.has(s.layoutId)&&!groups.some(g=>g.id===s.layoutId))delete s.layoutId;});}
function showOutlineLayoutPicker(index,trigger){const editing=outlineEditing(),o=editing?outlineDraft.value:current.outline;if(!o?.sections[index]||!outlineLayouts(index,o.sections.length).length)return;outlineLayoutPicker={taskId:current.id,index,editing,selectedId:outlineLayout(o.sections[index],index,o.sections.length)?.id||'',trigger};paintOutlineLayoutPicker();}
function paintOutlineLayoutPicker(){const p=outlineLayoutPicker,o=p.editing?outlineDraft.value:current.outline,groups=outlineLayouts(p.index,o.sections.length),selected=groups.find(g=>g.id===p.selectedId),active=outlineLayout(o.sections[p.index],p.index,o.sections.length),fixed=outlineRoleLayout(p.index,o.sections.length);$('modal').classList.add('outline-layout-picker');showModal(`第 ${p.index+1} 页 · ${fixed?'查看布局':'更换布局'}`,`<p class="outline-picker-title">${esc(o.sections[p.index].title)}</p><div class="outline-picker-body"><div class="outline-layout-options" role="group" aria-label="当前模板的已确认布局">${groups.map((g,i)=>`<button type="button" class="outline-layout-option" data-action="select-outline-layout" data-layout-id="${esc(g.id)}" aria-pressed="${g.id===p.selectedId}">${layoutDiagram(g)}<span><strong>${esc(g.name)}</strong><small>${g.id===active?.id?'当前布局':'布局 '+(i+1)}</small></span></button>`).join('')}</div><aside class="outline-layout-detail">${selected?`${layoutDiagram(selected)}<h3>${esc(selected.name)}</h3>${selected.representativeSlide?`<p>来源：模板第 ${esc(selected.representativeSlide)} 页</p>`:''}${fixed?'<p>此页使用模板的专用布局。</p>':''}`:'<p>请选择页面布局。</p>'}</aside></div>`,`<button data-action="close" autofocus>返回大纲</button>${fixed?'':`<button class="primary" data-action="apply-outline-layout" ${!selected||selected.id===active?.id?'disabled':''}>应用布局</button>`}`);}
async function applyOutlineLayout(){const p=outlineLayoutPicker;if(!p||p.taskId!==current?.id||p.editing!==outlineEditing())throw Error('大纲已更新，请关闭后重新选择布局。');const o=p.editing?outlineDraft.value:current.outline,group=outlineLayouts(p.index,o.sections.length).find(g=>g.id===p.selectedId);if(!group)throw Error('该布局不属于当前模板，请重新选择。');if(p.editing){o.sections[p.index].layoutId=group.id;$('outlineLayout'+p.index).outerHTML=outlineLayoutCard(o.sections[p.index],p.index,o.sections.length);$('modal').close();return;}const value=JSON.parse(JSON.stringify(o));value.sections[p.index].layoutId=group.id;const updated=await api(endpoint('outline'),value,'PUT');current=updated;outlineViewing=true;$('modal').close();render();notice('布局已保存');}
function outlineImageFields(s,i){if(current.creationMode==='update')return `<div class="outline-edit-description"><label for="sourcePages${i}">来源原页码</label><input id="sourcePages${i}" data-source-pages="${i}" value="${esc((s.sourcePages||[i+1]).join('、'))}" placeholder="例如：1、2"><p class="helper">保留对应原页的必要图片；拆合页时填写全部来源页码。</p></div>`;const image=s.image||{kind:'none'};return `<div class="outline-edit-description"><label for="outlineImageKind${i}">外部配图</label><select id="outlineImageKind${i}" data-outline-image="kind" data-index="${i}"><option value="none" ${image.kind!=='web'?'selected':''}>不配图（可使用原生流程图、形状或数据图）</option><option value="web" ${image.kind==='web'?'selected':''}>制作时网上找图（整套最多一张）</option></select><div id="outlineImageDetails${i}" ${image.kind==='web'?'':'hidden'}><label for="outlineImageSubject${i}">图片内容</label><input id="outlineImageSubject${i}" data-outline-image="subject" data-index="${i}" maxlength="100" value="${esc(image.subject||'')}" placeholder="例如：人脸伪造案例图"><label for="outlineImagePurpose${i}">教学用途</label><input id="outlineImagePurpose${i}" data-outline-image="purpose" data-index="${i}" maxlength="120" value="${esc(image.purpose||'')}" placeholder="例如：引出生成内容如何辨别真伪"><label for="outlineImageQuery${i}">检索关键词（可选，默认使用图片内容）</label><input id="outlineImageQuery${i}" data-outline-image="query" data-index="${i}" maxlength="160" value="${esc(image.query||'')}" placeholder="建议使用具体英文关键词"></div></div>`;}
function teachingObjective(o){return String(o.teachingObjective??(current.creationMode==='update'?'':o.objective??'')).trim();}
function outlineEditor(){const o=outlineDraft.value,objective=teachingObjective(o);return `<section class="panel outline-edit-panel"><div class="panel-heading"><div><h2>编辑教学大纲</h2><p class="helper">${current.creationMode==='update'?'每张卡片对应一页PPT，保留原稿内容并注明布局调整；需要改内容时在此明确说明，来源页码不可遗漏。':'每张卡片对应一页PPT，建议只写一个主题和2–3个短要点，详细讲解留给逐页讲稿。'}保存后先整体查看，确认后才开始制作。</p></div><button data-action="cancel-outline-edit">取消编辑</button></div><form id="outlineEditor" novalidate>${objective?`<label for="outlineObjective">教学目标</label><textarea id="outlineObjective" data-outline-field="${o.teachingObjective!==undefined||current.creationMode==='update'?'teachingObjective':'objective'}" maxlength="2000">${esc(objective)}</textarea>`:''}<div class="outline-edit-list">${o.sections.map((s,i)=>`<article class="outline-edit-card"><header><span class="outline-edit-number">${i+1}</span><strong>${o.pageBased?'第 '+(i+1)+' 页':'旧版环节 '+(i+1)}</strong><div class="outline-edit-tools"><button type="button" data-action="outline-up" data-index="${i}" ${i===0?'disabled':''} aria-label="上移第${i+1}个板块">↑ 上移</button><button type="button" data-action="outline-down" data-index="${i}" ${i===o.sections.length-1?'disabled':''} aria-label="下移第${i+1}个板块">↓ 下移</button><button type="button" data-action="outline-add-after" data-index="${i}" ${o.sections.length>=150?'disabled':''}>＋ 在下方新增</button><button type="button" class="text-button" data-action="outline-delete" data-index="${i}" ${o.sections.length===1?'disabled':''} aria-label="删除第${i+1}个板块">删除</button></div></header><div class="outline-edit-body"><div class="outline-edit-fields"><div><label for="outlineTitle${i}">标题</label><input id="outlineTitle${i}" data-outline-field="title" data-index="${i}" maxlength="200" value="${esc(s.title)}"></div><div><label for="outlineMinutes${i}">时长（分钟）</label><input id="outlineMinutes${i}" data-outline-field="minutes" data-index="${i}" type="number" min="0.5" max="240" step="0.5" value="${esc(s.minutes)}"></div><div class="outline-edit-description"><label for="outlineDescription${i}">本页展示内容、图示与课堂安排</label><textarea id="outlineDescription${i}" data-outline-field="description" data-index="${i}" maxlength="6000">${esc(s.description)}</textarea></div>${outlineImageFields(s,i)}</div>${outlineLayoutSelect(s,i)}</div></article>`).join('')}</div><button type="button" class="outline-add-button" data-action="outline-add" ${o.sections.length>=150?'disabled':''}>＋ 新增一页</button><p id="outlineEditorError" class="error-text" role="alert"></p><div class="outline-edit-footer"><p id="outlineTotal" role="status"></p><button type="submit" class="primary">保存大纲</button></div></form></section>`;}
async function saveOutlineDraft(){const o=outlineDraft.value,errorTarget=$('outlineEditorError');const invalid=o.sections.findIndex(s=>!s.title.trim()||!Number.isFinite(Number(s.minutes))||Number(s.minutes)<=0);const imagePages=o.sections.filter(s=>s.image?.kind==='web');let message=imagePages.length>1?'整套PPT最多一张外部配图，请仅保留一页网上找图。':imagePages.some(s=>!s.image.subject?.trim()||!s.image.purpose?.trim())?'请填写配图内容和教学用途。':o.pageBased&&current.pageCount&&o.sections.length!==current.pageCount?`请将大纲调整为 ${current.pageCount} 页，当前为 ${o.sections.length} 页。`:o.pageBased&&o.sections.some(s=>!s.description.trim())?'请填写每一页展示的内容。':invalid>=0?`请填写第 ${invalid+1} 个板块的标题和有效时长。`:Math.abs(outlineTotal()-current.minutes)>.01?'请调整各板块时长，使合计等于本课课时。':'';if(message){if(errorTarget)errorTarget.textContent=message;if($('modal')?.open&&$('modalError'))$('modalError').textContent=message;document.getElementById(invalid>=0?`outlineTitle${invalid}`:'outlineTotal')?.scrollIntoView({block:'nearest'});return false;}if(!outlineDirty()){outlineDraft=null;outlineViewing=true;return true;}current=await api(endpoint('outline'),o,'PUT');outlineDraft=null;outlineViewing=true;return true;}
function durationLabel(ms){const seconds=Math.max(0,Math.floor(ms/1000));return `${Math.floor(seconds/60)}分${String(seconds%60).padStart(2,'0')}秒`;}
function paintRunningProgress(){const target=$('runningProgress');if(target&&current?.status==='running'&&window.PptExecutionView)window.PptExecutionView.update(target,current.run);}
function outlinePage(){if(outlineEditing())return outlineEditor();const o=current.outline,objective=teachingObjective(o);return `<section class="panel"><div class="panel-heading"><h2>${o.pageBased?'逐页教学大纲':'旧版教学环节大纲'}</h2></div>${objective?`<p class="objective"><strong>教学目标</strong> ${esc(objective)}</p>`:''}${!o.pageBased?'<p class="callout">这是旧版环节大纲。请重新生成逐页大纲，确认每页内容后再制作。</p>':''}${o.sections.map((s,i)=>`<article class="outline-row outline-layout-row ${outlineLayouts(i,o.sections.length).length?'has-layout':''}"><span class="num">${o.pageBased?'第'+(i+1)+'页':i+1}</span><div class="outline-page-content"><div class="outline-page-heading"><strong>${esc(s.title)}</strong><span class="duration">${s.minutes} 分钟</span></div>${s.sourcePages?`<small class="helper">来源：原第 ${s.sourcePages.join('、')} 页</small>`:''}<p>${esc(s.description)}</p>${o.pageBased?`<p class="helper">${s.image?.kind==='web'?'制作时配图：'+esc(s.image.subject)+' · 用途：'+esc(s.image.purpose):current.creationMode==='update'?'保留原稿必要配图':'不配外部图片'}</p>`:''}<button type="button" class="text-button" data-action="edit-outline" data-index="${i}">编辑大纲</button></div>${outlineLayoutCard(s,i,o.sections.length)}</article>`).join('')}<div class="outline-actions"><button data-action="edit-outline">调整大纲</button><p>合计 ${current.minutes} 分钟${current.pageCount?` · PPT 共 ${current.pageCount} 页`:current.creationMode==='update'?' · 保留原稿页数':' · 页数自动安排'}</p>${o.pageBased?'<button class="primary" data-action="confirm-outline">确认全部页面，生成PPT</button>':'<button class="primary" data-action="regenerate-outline">重新生成逐页大纲</button>'}</div><form id="outlineAdvice" class="feedback-form"><input id="outlineNote" maxlength="1000" aria-label="大纲补充要求" placeholder="补充调整建议，将重新调用模型"><button>发送调整建议</button></form></section>`;}
function versionData(){return current.versions.find(v=>v.number===selectedVersion)||current.versions.at(-1);}
function deckPage(){const v=versionData();if(selectedPage>=v.slides.length)selectedPage=0;const s=v.slides[selectedPage],latest=v.number===current.versions.at(-1).number;return `<div class="workspace"><section class="panel"><div class="panel-heading"><div><h2>课件内容与交付文件</h2><p class="helper">版本 ${v.number} · ${v.slides.length} 页</p></div>${tag(current)}</div><div class="deck-workspace"><nav class="slide-list" aria-label="课件页面">${v.slides.map((s,i)=>`<button class="slide-item ${i===selectedPage?'active':''}" aria-pressed="${i===selectedPage}" data-action="slide" data-index="${i}"><span class="slide-mini">${esc(s.text.split('\n')[0]||'图片页面')}</span>第 ${i+1} 页</button>`).join('')}</nav><div class="deck-main"><div class="content-preview"><span class="tag">${v.previews?.[selectedPage]?"源文件页面预览":"从PPTX提取的文字内容"}</span><h2>第 ${selectedPage+1} 页</h2>${v.previews?.[selectedPage]?`<img class="source-preview" src="${download(v.previews[selectedPage])}&inline=1" alt="${selectedPage+1}">`:""}<pre>${esc(s.text||'本页未提取到文字，请下载PPTX查看图片或图形。')}</pre></div><p class="helper">此处是内容核对视图，不代表真实排版。请下载后在 PowerPoint 中检查投影、公式和图片。</p></div></div><div class="artifact-strip"><span class="file-icon">PPTX</span><div><strong>${esc(current.title)}.pptx</strong><p>版本 ${v.number} · SHA256 ${v.sha256.slice(0,12)}</p></div><a class="download-button" href="${download(v.file)}">下载PPTX</a></div>${v.sources.map(f=>`<p><a href="${download(f.file)}">下载源文件：${esc(f.name)}</a></p>`).join('')}${current.deliverySummary?`<details class="callout"><summary>制作反馈与检查记录</summary><p class="helper">以下为制作工具的反馈，课件仍需教师核对。</p><div class="pre-wrap">${esc(current.deliverySummary)}</div></details>`:''}</section><aside class="result-sidebar"><section class="aside-note readiness-card"><h3>检查后，再带进课堂</h3><p>核对知识点、例题答案、备注，以及实际投影下的字体与排版。</p><label class="ready-check"><input id="reviewed" type="checkbox" ${current.reviewedVersion===v.number?'checked':''} ${!latest?'disabled':''}>我已核对课件内容与实际呈现</label><button class="primary side-action" data-action="ready" ${!latest||current.reviewedVersion!==v.number?'disabled':''}>${current.reviewedVersion===v.number?'已标记可上课':'标记可上课'}</button></section><section class="aside-note modification-card"><h3>提出修改要求</h3><p>对照当前课件，直接描述希望怎么改。</p><label for="changeSlide">修改页面</label><select id="changeSlide">${v.slides.map((s,i)=>`<option value="${i}" ${i===selectedPage?'selected':''}>第 ${i+1} 页</option>`).join('')}</select><label for="changeText">修改内容</label><textarea id="changeText" aria-label="修改要求" maxlength="2000" placeholder="例如：将这一页例题换成生活情境，分三个步骤讲解。">${esc(changeDrafts[current.id]?.[selectedPage]||'')}</textarea><p class="helper">切页会保留未发送文字。修改生成新版本，旧版保留。</p><button class="primary side-action" data-action="change" ${!latest||!connection.ready?'disabled':''}>提交修改</button>${!connection.ready?'<p class="helper">自动修改待配置；可在外部修改后导回新版本。</p>':''}</section><section class="aside-note history-card"><h3>历史版本</h3>${[...current.versions].reverse().map(v=>`<div class="version"><strong>版本 ${v.number}${latest&&v.number===versionData().number?' · 当前':''}</strong><button data-action="version" data-index="${v.number}">查看</button></div>`).join('')}</section>${importBox()}</aside></div>`;}
function htmlData(){return current.htmlVersions?.find(v=>v.number===selectedHtmlVersion)||current.htmlVersions?.at(-1);}
function htmlPage(){const v=htmlData();if(selectedPage>=v.slides.length)selectedPage=0;return window.PptHtmlView.render({task:current,version:v,page:selectedPage,draft:changeDrafts[current.id]?.[selectedPage]||'',connected:connection.ready,exportConnected:connection.exportReady!==false,exportReason:connection.exportReason});}
function feedbackPage(){if(outlineEditing())return outlineEditor();if(outlineViewing&&current.outline)return outlinePage();if(current.status==='outline')return outlinePage();if(htmlData()&&(showHtmlPreview||['html-ready','complete','ready'].includes(current.status)||current.run?.phase==='export'&&['running','failed','cancelled'].includes(current.status)))return htmlPage();if(['complete','ready'].includes(current.status))return deckPage();if(['prepared','manual'].includes(current.status))return manualPage();return `<div class="workspace"><section class="panel status-card ${current.status==='failed'?'error-card':''}"><div class="status-symbol">${current.status==='running'?'▧':'!'}</div><h2>${current.status==='running'?(current.run.phase==='outline'?'正在整理教学大纲':current.run.phase==='export'?'正在导出可编辑PPT':'正在生成PPT'):current.status==='cancelled'?'本轮制作已取消':'制作暂未完成'}</h2><p>${esc(teacherMessage(current.error)||'制作已在后台进行，可以切换到其他板块；完成、需要确认或失败时会在侧栏PPT管理提示。教学要求与已有版本会保留。')}</p>${current.status==='running'?'<div id="runningProgress"></div>':''}<div class="status-actions">${current.status==='running'?'<button class="danger" data-action="cancel">取消本次制作</button>':(current.run?.phase==='html'?'<button class="primary" data-action="resume-html" disabled>检查可续做进度…</button><button data-action="retry">全部重新生成</button>':'<button class="primary" data-action="retry">重新发起</button>')+'<button data-action="manual">改用手动调用</button>'}</div>${current.run?.phase==='html'&&['failed','cancelled'].includes(current.status)?'<p id="resumeStatus" role="status"></p>':''}<div class="status-secondary-actions">${current.status==='failed'&&current.run?.phase==='outline'?'<button class="text-button" data-action="edit-requirements">调整课件要求</button>':''}${htmlData()?'<button class="text-button" data-action="view-html">查看课件</button>':''}${current.outline?'<button class="text-button" data-action="edit-outline">\u67e5\u770b\u5e76\u8c03\u6574\u5927\u7eb2</button>':''}${current.versions.length?'<button class="text-button" data-action="previous-version">查看已有版本</button>':''}</div></section><aside class="aside-note"><h3>阶段反馈</h3>${current.feedback.slice(-8).map(f=>`<div class="version"><span>${esc(teacherMessage(f.message))}</span></div>`).join('')}</aside></div>`;}
let templateItems=[],unmountTemplateUpload=null,templateReview=null,templateReviewState=null;
function templateField(){return `<section class="template-field"><h3>课件模板（可选）</h3><p class="helper"><a href="/preparation?type=ppt&section=templates#list">管理模板库</a></p><p class="helper">${current.creationMode==='update'?'复用模板的字体、配色和版式，保留原稿内容。':'复用模板的字体、配色和版式，课程内容按本次要求重新制作。'}上传后先拆解并确认最小布局集，再供课件复用。</p><label for="pptTemplate">选择已保存模板</label><select id="pptTemplate"><option value="">不使用模板</option>${templateItems.map(t=>`<option value="${t.id}" ${current.template?.id===t.id?'selected':''}>${esc(t.displayName||t.name)} · ${t.profile.confirmed?t.profile.slideCount+' 种已确认布局':t.profile.slideCount+' 页 · 待拆解确认'}</option>`).join('')}</select>${current.template?`<p class="helper">已选：<a href="${download(current.template.file)}">${esc(current.template.name)}</a> · ${current.template.profile.confirmed?current.template.profile.slideCount+' 种布局':'旧模板待拆解确认'} <button type="button" data-action="review-template">查看并确认布局</button></p>`:''}<div id="templateUpload" class="reference-upload"></div><p id="templateError" class="error-text" role="alert" hidden></p>${templateReview?templateReviewPanel():''}</section>`;}
function layoutDiagram(group){const labels={title:'标题',text:'正文',image:'图片',table:'表格',chart:'图表',group:'组合',line:'线条',shape:'形状'};return `<svg viewBox="0 0 320 180" role="img" aria-label="${esc(group.name)}布局结构示意"><rect width="320" height="180" fill="#f5f8fc"/>${(group.shapes||[]).filter(s=>[s.x,s.y,s.w,s.h].every(Number.isFinite)).slice(0,60).map(shape=>{const x=Math.max(-320,Math.min(640,shape.x*320)),y=Math.max(-180,Math.min(360,shape.y*180)),w=Math.max(1,Math.min(640,shape.w*320)),h=Math.max(1,Math.min(360,shape.h*180));return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="2" fill="${shape.kind==='image'?'#d6e5ef':'#e6edf8'}" stroke="#8da6c4"/>${w>30&&h>13?`<text x="${x+4}" y="${y+12}" font-size="10" fill="#446080">${labels[shape.kind]||'区域'}</text>`:''}`;}).join('')}</svg>`;}
function openTemplateReview(item){templateReview=item;templateReviewState=null;}
function reviewState(){const item=templateReview;if(!templateReviewState||templateReviewState.id!==item.id){const names=Object.fromEntries(item.analysis.layoutGroups.map(g=>[g.id,item.profile.layoutGroups?.find(v=>v.id===g.id)?.name||g.name])),kept=item.profile.confirmed?item.profile.layoutGroups.map(g=>g.id):item.analysis.layoutGroups.map(g=>g.id);templateReviewState={id:item.id,mode:'smart',smart:{ids:new Set(item.analysis.smart.selectedIds),names:Object.fromEntries(item.analysis.smart.selectedIds.map((id,i)=>{const group=item.analysis.layoutGroups.find(g=>g.id===id),saved=item.profile.confirmed?item.profile.layoutGroups.find(g=>g.id===id):null;return [id,saved&&saved.name!==group.name?saved.name:'布局 '+(i+1)];}))},manual:{ids:new Set(kept),names:{...names}}};}return templateReviewState;}
function bindTemplateChoices(){const panel=$('templateReview');if(panel){panel.oninput=captureTemplateChoices;panel.onchange=captureTemplateChoices;updateTemplateSummary();}}
function captureTemplateChoices(){const state=reviewState(),choice=state[state.mode];choice.ids=new Set();document.querySelectorAll('[data-template-layout]').forEach(el=>{if(el.checked)choice.ids.add(el.dataset.templateLayout);choice.names[el.dataset.templateLayout]=document.getElementById('layoutName-'+el.dataset.templateLayout).value;});updateTemplateSummary();}
function updateTemplateSummary(){if(!templateReview)return;const state=reviewState(),count=state[state.mode].ids.size,summary=$('templateSelectionSummary'),button=$('confirmTemplateLayouts');if(summary)summary.textContent=`已选 ${count} 种布局，将生成 ${count} 页精简模板。`;if(button){button.textContent=`确认生成 ${count} 页模板并用于本课件`;button.disabled=count===0;}}
function templateReviewPanel(){const item=templateReview,state=reviewState(),smart=state.mode==='smart',choice=state[state.mode],groups=smart?item.analysis.smart.representatives.map(r=>({...item.analysis.layoutGroups.find(g=>g.id===r.id),...r})):item.analysis.layoutGroups;return `<section id="templateReview" class="template-review" aria-labelledby="templateReviewTitle"><h3 id="templateReviewTitle">确认可复用布局</h3><div class="template-mode-switch" role="group" aria-label="布局选择方式"><button type="button" data-action="template-mode-smart" aria-pressed="${smart}">智能精简（推荐）</button><button type="button" data-action="template-mode-manual" aria-pressed="${!smart}">手动选择</button></div><p>${esc(item.name)}：原文件 ${item.analysis.slideCount} 页，${smart?'智能推荐 '+groups.length+' 种代表布局':'共 '+groups.length+' 种候选布局，可逐一选择和命名'}。</p><p class="helper">${smart?'按正文、图片、表格等区域的位置、大小和类型比较相似度，合并近似布局，保留差异较大的代表页。可切换手动选择，找回其他候选布局。':'这里保留全部结构候选，支持逐个勾选、修改名称。切换方式会保留本次选择。'}</p><p class="helper">下方为去掉旧课程文字的布局示意，非实际成品预览。确认后只将保留布局的代表页交给制作工具，原文件保留。</p><div class="template-layout-grid">${groups.map((g,i)=>`<article class="template-layout-card"><strong class="template-layout-number">${smart?'推荐':'候选'}布局 ${i+1} / ${groups.length}</strong>${layoutDiagram(g)}<label class="layout-keep"><input type="checkbox" data-template-layout="${esc(g.id)}" ${choice.ids.has(g.id)?'checked':''}>保留此布局</label><label for="layoutName-${esc(g.id)}">布局名称</label><input id="layoutName-${esc(g.id)}" maxlength="60" value="${esc(choice.names[g.id]||g.name)}"><p class="helper">来源：原文件第 ${g.representativeSlide} 页 · ${smart?'覆盖':'共'} ${g.sourceSlides.length} 页${smart&&g.candidateIds.length>1?' · 合并 '+g.candidateIds.length+' 种近似候选':''}</p></article>`).join('')}</div><p id="templateSelectionSummary" class="helper" role="status">已选 ${choice.ids.size} 种布局，将生成 ${choice.ids.size} 页精简模板。</p><div class="savebar"><button type="button" data-action="cancel-template-review">暂不使用这些布局</button><button id="confirmTemplateLayouts" type="button" class="primary" data-action="confirm-template-layouts" ${choice.ids.size?'':'disabled'}>确认生成 ${choice.ids.size} 页模板并用于本课件</button></div></section>`;}
function templateError(message){const target=$('templateError');if(target){target.textContent=message;target.hidden=!message;}}
async function mountTemplateUpload(){
 const select=$('pptTemplate');if(!select)return;const epoch=viewEpoch;
 try{const data=await api('/api/ppt/templates');if(epoch!==viewEpoch||!select.isConnected)return;templateItems=data.items;select.innerHTML='<option value="">不使用模板</option>'+templateItems.map(t=>`<option value="${t.id}" ${current.template?.id===t.id?'selected':''}>${esc(t.displayName||t.name)} · ${t.profile.confirmed?t.profile.slideCount+' 种已确认布局':t.profile.slideCount+' 页 · 待拆解确认'}</option>`).join('');}catch(e){if(epoch===viewEpoch)templateError(e.message);}
 select.onchange=()=>perform(async()=>{const templateId=select.value;if(!await saveForm())return;if(!templateId){current=await api(endpoint('template'),{templateId},'PUT');templateReview=null;}else{const selected=await api('/api/ppt/templates/'+templateId+'/analyze',{});if(selected?.profile.confirmed){current=await api(endpoint('template'),{templateId,confirmationRevision:selected.confirmedRevision},'PUT');templateReview=null;}else openTemplateReview(await api('/api/ppt/templates/'+templateId+'/analyze',{}));}render();document.getElementById('templateReview')?.scrollIntoView({block:'start'});});
 if(epoch!==viewEpoch||!window.InclassUpload||!$('templateUpload'))return;
 unmountTemplateUpload=window.InclassUpload.mount($('templateUpload'),{accept:'.pptx',multiple:false,limit:1,label:'将PPT模板拖到此处，或',types:'PPTX · 不超过20MB · 保存到模板库后可重复选用',exceedText:'请一次上传一份PPTX模板。',files:[],getFiles:()=>[],onError:templateError,onSelect:async chosen=>{if(chosen.length!==1||!chosen[0].size||chosen[0].size>20*1024*1024||!/\.pptx$/i.test(chosen[0].name)){templateError('请选择一份不超过20MB的有效PPTX模板。');return;}if(actionPending){templateError('正在保存，请稍后再上传。');return;}await perform(async()=>{if(!await saveForm())return;const uploaded=await api('/api/ppt/templates',await fileValue(chosen[0]));if(uploaded.profile.confirmed){current=await api(endpoint('template'),{templateId:uploaded.id,confirmationRevision:uploaded.confirmedRevision},'PUT');templateReview=null;render();notice('已复用模板的确认布局');}else{openTemplateReview(uploaded);render();document.getElementById('templateReview')?.scrollIntoView({block:'start'});notice('模板已拆解，请确认要保留的布局');}});}});
}
function unmountUpload(){if(unmountReferenceUpload){unmountReferenceUpload();unmountReferenceUpload=null;}if(unmountTemplateUpload){unmountTemplateUpload();unmountTemplateUpload=null;}}
let resumeState=null;
async function loadResume(){const taskId=current.id,epoch=viewEpoch;try{const info=await api(endpoint('resume-info'));if(current?.id!==taskId||viewEpoch!==epoch)return;resumeState=info;const button=document.querySelector('[data-action="resume-html"]');if(button){button.disabled=!info.available;button.textContent=info.available?(info.completed===info.total?'收集已完成的全部页面':`从第 ${info.completed+1} 页继续生成`):'暂无可续做页面';}if($('resumeStatus'))$('resumeStatus').textContent=info.available?`已完成 ${info.completed} / ${info.total} 页；续做会保留这些页面和讲稿。`:info.reason;}catch(e){if(current?.id===taskId&&viewEpoch===epoch&&$('resumeStatus'))$('resumeStatus').textContent='进度检查失败：'+e.message;}}
function render(){if(step>=3&&current.status!=='running'&&!outlineViewing)window.parent.PptNotifications?.shown(current);unmountUpload();viewEpoch++;error('');$('view').innerHTML=frame()+(step===1?requirements():step===2?methodPage():feedbackPage())+footer();bind();if(document.querySelector('[data-action="resume-html"]')){resumeState=null;loadResume();}if(step===3&&['prepared','manual'].includes(current.status))loadPrompt().catch(e=>error(e.message));if(current.status==='running'){window.parent.PptNotifications?.track(current);paintRunningProgress();if(!poll)poll=setInterval(refresh,2000);if(!progressClock)progressClock=setInterval(paintRunningProgress,1000);}if(current.status!=='running')stopPoll();}
function draft(){return {pageCountPolicy:current.pageCountPolicy||'preserve',creationMode:current.creationMode||'create',sourceFileId:$('sourceFileId')?.value||current.sourceFileId||'',presenter:$('presenter')?.value.trim()||'',lessonDate:$('lessonDate')?.value||'',title:$('title').value.trim(),audience:$('audience').value.trim(),minutes:Number($('minutes').value),pageCount:$('pageCount').value===''?null:Number($('pageCount').value),content:$('content').value.trim(),courseId:$('course').value,style:$('style').value,extra:$('extra').value};}
async function saveForm(next=false){if(next&&templateReview){templateError('请先确认要保留的模板布局，或关闭布局选择后再继续。');document.getElementById('templateReview')?.scrollIntoView({block:'start'});return false;}const b=draft();if(b.pageCount!==null&&(!Number.isInteger(b.pageCount)||b.pageCount<1||b.pageCount>150)){const field=$('pageCount');$('pageCountError').textContent='请输入1至150之间的整数，或留空自动安排。';field.setAttribute('aria-invalid','true');field.focus();return false;}$('pageCountError').textContent='';$('pageCount').removeAttribute('aria-invalid');if(next&&(!b.title||!b.audience||(!b.content&&!current.files.length))){$('formError').textContent='请填写主题、授课对象，以及教学内容或参考资料。';return false;}current=await api(current.id?endpoint():'/api/ppt/tasks',b,current.id?'PUT':'POST');location.hash='task/'+current.id;if(next&&current.creationMode==='update'){const source=await api(endpoint('source-info'),{});current.sourcePageCount=source.pageCount;if(current.pageCount&&Math.abs(source.pageCount-current.pageCount)>=5&&current.pageCountAcknowledged!==`${current.sourceFileId}:${source.pageCount}:${current.pageCount}`){showModal('原稿与目标页数差异较大',`<p>原稿 <strong>${source.pageCount} 页</strong>，目标 <strong>${current.pageCount} 页</strong>，相差 ${Math.abs(source.pageCount-current.pageCount)} 页。</p><p>按原稿页数：尽量保留原内容和页序，主要更新排版。</p><p>按目标页数：模型会对内容进行${current.pageCount<source.pageCount?'精简、归纳和合并':'扩充、解释和拆分'}，部分内容或表达将发生调整；仍需先确认大纲，再制作课件。</p>`,`<button data-action="close" autofocus>返回修改</button><button data-action="page-count-original">按原稿 ${source.pageCount} 页</button><button class="primary" data-action="page-count-target">按目标 ${current.pageCount} 页</button>`);return false;}}if(next){step=2;connection=await api('/api/ppt/connection');render();}return true;}
async function fileValue(file){if(!file||!file.size||file.size>20*1024*1024)throw new Error('请选择不超过20MB的有效文件。');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('文件读取失败。'));reader.readAsDataURL(file);});return {name:file.name,base64};}
let manualPrompt='';
async function loadPrompt(){const taskId=current.id,epoch=viewEpoch,p=await api(endpoint('prompt'));if(current?.id===taskId&&viewEpoch===epoch)manualPrompt=p.text;}
async function refresh(){if(!current?.id||actionPending)return;const taskId=current.id,epoch=viewEpoch;try{const t=await api(endpoint());if(current?.id!==taskId||viewEpoch!==epoch)return;if(t.status==='running'&&current.status==='running'&&t.run?.id===current.run?.id){current=t;paintRunningProgress();return;}if(t.status!==current.status||t.updatedAt!==current.updatedAt){if(t.status==='html-ready'){selectedHtmlVersion=null;showHtmlPreview=false;if(t.run?.phase==='html-modify'&&changeDrafts[t.id])delete changeDrafts[t.id][t.run.page-1];}if(t.status==='complete'){selectedVersion=null;if(t.run?.phase==='modify'&&changeDrafts[t.id])delete changeDrafts[t.id][t.run.page-1];}current=t;render();}}catch(e){error('刷新进度失败：'+e.message);}}

function referenceError(message){const target=$('referenceUploadError');if(target){target.textContent=message;target.hidden=!message;}else error(message);}
function referenceFiles(){return current.files.map(f=>({uid:f.id,id:f.id,name:f.name,status:'success',url:download(f.file)}));}
function mountReferenceUpload(){
 if(!$('referenceUpload'))return;
 if(!window.InclassUpload){referenceError('\u4e0a\u4f20\u7ec4\u4ef6\u52a0\u8f7d\u5931\u8d25\uff0c\u8bf7\u4fdd\u5b58\u8349\u7a3f\u540e\u5237\u65b0\u91cd\u8bd5\u3002');return;}
 unmountReferenceUpload=window.InclassUpload.mount($('referenceUpload'),{
  files:referenceFiles(),getFiles:referenceFiles,onError:referenceError,
  onPreview:file=>{if(file.url){const link=document.createElement('a');link.href=file.url;link.download=file.name;link.click();}},
  onSelect:async chosen=>{
   if(actionPending){referenceError('\u6b63\u5728\u4fdd\u5b58\uff0c\u8bf7\u7a0d\u540e\u518d\u4e0a\u4f20\u3002');return;}
   referenceError('');
   if(current.files.length+chosen.length>12){referenceError('\u6bcf\u4e2a\u4efb\u52a1\u6700\u591a12\u4efd\u53c2\u8003\u8d44\u6599\u3002');return;}
   for(const f of chosen){if(!/\.(pdf|docx|pptx|txt|md|png|jpe?g)$/i.test(f.name)||!f.size||f.size>20*1024*1024){referenceError('\u8bf7\u9009\u62e9\u652f\u6301\u7684\u975e\u7a7a\u6587\u4ef6\uff0c\u6bcf\u4efd\u4e0d\u8d85\u8fc720MB\u3002');return;}}
   await perform(async()=>{if(!await saveForm())return;try{for(const f of chosen)current=await api(endpoint('files'),await fileValue(f));}finally{render();}notice('\u53c2\u8003\u8d44\u6599\u5df2\u4fdd\u5b58\u5728\u672c\u673a');});
  },
  onRemove:file=>perform(async()=>{if(!await saveForm())return;current=await api(endpoint('files'),{fileId:file.id},'DELETE');render();})
 });
}

function positionCards(){const sidebar=document.querySelector(".result-sidebar"),deck=document.querySelector(".deck-main"),ready=document.querySelector(".readiness-card"),change=document.querySelector(".modification-card");if(!sidebar||!deck||!ready||!change)return;if(matchMedia("(max-width:1000px)").matches)deck.querySelector(".content-preview,.html-slide-frame")?.after(ready,change);else sidebar.prepend(ready,change);}
