 if(a==='open'){templateReview=null;outlineViewing=false;selectedHtmlVersion=null;showHtmlPreview=false;outlineDraft=null;viewEpoch++;stopPoll();current=await api('/api/ppt/tasks/'+button.dataset.id);location.hash='task/'+current.id;method=current.deliveryMethod==='auto'?'auto':'manual';step=current.status==='draft'?1:3;selectedVersion=null;selectedPage=0;return render();}
